    private BatchOptions Options(){if(!int.TryParse(_font.Text,out int font))throw new InvalidDataException("Nhập cỡ watermark từ8–96 px.");var options=new BatchOptions(_format.SelectedItem?.ToString()??"PNG",_pattern.Text,_edge.SelectedIndex switch{1=>1280,2=>1920,3=>3840,_=>0},_watermark.Text,font,_watermarkPosition.SelectedIndex,_watermarkOpacity.Value,_logoPng);options.Validate();return options;}
