    private void Report(){var save=new SaveFileDialog{Filter="Báo cáo CSV|*.csv",FileName="Captovix-export.csv"};if(save.ShowDialog(this)!=true)return;try{if(_jobs.Any(j=>j.Item.FilePath.Equals(save.FileName,StringComparison.OrdinalIgnoreCase)))throw new IOException("Không ghi đè ảnh gốc.");string Cell(string s)=>"\""+(s.Length>0&&"=+-@".Contains(s[0])?"'":"")+s.Replace("\"","\"\"")+"\"";File.WriteAllText(save.FileName,"Tên ảnh,File xuất,Trạng thái\n"+string.Join('\n',_jobs.Select(j=>string.Join(',',new[]{j.Item.Title,j.Output,j.Status}.Select(Cell)))),new UTF8Encoding(true));}catch(Exception ex){_status.Text=ex.Message;}}
