public partial class MainWindow
{
    private void BatchExport_Click(object sender,RoutedEventArgs e)=>OpenBatchExport(MediaList.SelectedItems.Cast<MediaItem>().ToArray());
    private void OpenBatchExport(MediaItem[] items){if(!RequireLicense())return;if(_busy||_updateApplying||!FlushEdits())return;if(items.Count(i=>!i.IsVideo)>500){SetStatus("Chọn tối đa500 ảnh mỗi lượt xuất.");return;}SetBusy(true);_captureCancellation=new();try{var window=new BatchExportWindow(items){Owner=DialogOwner};using var registration=_captureCancellation.Token.Register(()=>Dispatcher.BeginInvoke(window.Close));window.ShowDialog();}finally{_captureCancellation.Dispose();_captureCancellation=null;SetBusy(false);if(_exitRequested)_=Dispatcher.BeginInvoke(RequestExit);}}
}
